      >
        <i class="fas fa-plus text-lg"></i>
        <span class="text-[10px]">New</span>
      </button>

      <button
        v-if="activeChat"
        class="flex flex-col items-center gap-0.5 px-4 py-1.5 rounded-xl transition-colors"
        :class="showGroupInfo ? 'text-primary' : 'text-base-content/50 hover:'"
